export class ParseError extends Error {}

const NAME = /^[A-Za-z0-9_-]+$/
const COUNT = /^[1-9][0-9]*$/

export function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  let names = null
  const ballots = []
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    const fail = (m) => { throw new ParseError(`line ${n}: ${m}`) }
    if (t[0] === 'candidates') {
      if (names !== null || ballots.length) fail('candidates must be declared once, before any ballot')
      if (t.length < 2) fail('expected candidates <name>...')
      names = []
      for (const name of t.slice(1)) {
        if (!NAME.test(name)) fail(`invalid candidate name ${name}`)
        if (names.includes(name)) fail(`candidate ${name} is declared twice`)
        names.push(name)
      }
    } else if (t[0] === 'ballot') {
      if (names === null) fail('candidates must be declared once, before any ballot')
      if (t.length < 3) fail('expected ballot <count> <candidate>...')
      if (!COUNT.test(t[1])) fail('count must be a positive integer')
      const seen = []
      for (const name of t.slice(2)) {
        if (!names.includes(name)) fail(`unknown candidate ${name}`)
        if (seen.includes(name)) fail(`candidate ${name} is repeated`)
        seen.push(name)
      }
      ballots.push({ count: BigInt(t[1]), prefs: seen })
    } else fail(`unknown directive ${t[0]}`)
  }
  if (names === null) throw new ParseError('no candidates')
  return { names, ballots }
}

const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

export function count({ names, ballots }) {
  const continuing = new Set(names)
  const history = []
  const rounds = []
  for (;;) {
    const votes = new Map([...continuing].map((c) => [c, 0n]))
    let exhausted = 0n
    let active = 0n
    for (const b of ballots) {
      const c = b.prefs.find((p) => continuing.has(p))
      if (c === undefined) exhausted += b.count
      else { votes.set(c, votes.get(c) + b.count); active += b.count }
    }
    history.push(votes)
    const listing = [...votes].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : cmp(a[0], b[0])))
    const round = { listing, exhausted, eliminated: null }
    rounds.push(round)
    if (active === 0n) return { rounds, winner: null }
    const top = listing.find(([, v]) => v * 2n > active)
    if (top) return { rounds, winner: top[0] }
    let min = listing[listing.length - 1][1]
    let tied = listing.filter(([, v]) => v === min).map(([c]) => c)
    for (;;) {
      if (tied.length === 1) break
      const r = history.find((h) => new Set(tied.map((c) => h.get(c))).size > 1)
      if (!r) break
      const m = tied.map((c) => r.get(c)).reduce((a, b) => (b < a ? b : a))
      tied = tied.filter((c) => r.get(c) === m)
    }
    const out = tied.reduce((a, b) => (b > a ? b : a))
    round.eliminated = out
    continuing.delete(out)
  }
}
EOF
