#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */
import { readFileSync } from 'node:fs'
import { parse, count, ParseError } from './election.js'

function die(msg) {
  process.stderr.write(`error: ${msg}\n`)
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) die('usage: cli.js rounds|tally')

let election
try {
  election = parse(readFileSync(0, 'utf8'))
} catch (e) {
  if (e instanceof ParseError) die(e.message)
  throw e
}
const { rounds, winner } = count(election)
